    left = 0
    right = len(nums) - 1
    max_product = nums[left] * nums[right]
    while left < right:
        product = nums[left] * nums[right]
        if product > max_product:
            max_product = product
        if nums[left] < 0:
            break
        else:
            left += 1
            right -= 1
    return (max_product, max_product if max_product > 0 else 0)

