def max_sum_increasing_subseq(arr, i, k, n):
    # Create a table to store results of subproblems
    dp = [[0 for _ in range(n)] for _ in range(i+1)]

    # Initialize the first row of the table
    for j in range(1, n):
        dp[0][j] = arr[j]

    # Fill the table in a bottom-up manner
    for ind in range(1, i+1):
        for j in range(ind, n):
            # If current element is greater than previous element, update dp[ind][j]
            if arr[j] > dp[ind-1][j-1]:
                dp[ind][j] = max(dp[ind][j], dp[ind-1][j-1] + arr[j])
            # If current element is not greater than previous element, use the previous element's value
            else:
                dp[ind][j] = dp[ind][j-1]

    # Find the maximum sum including the kth element
    max_sum = 0
    for j in range(k, n):
        max_sum = max(max_sum, dp[i][j])

    return max_sum

